import {WEAPON_ORDER} from './weapon-order.js';
import {WEAPON_SLOTS,SLOT_LABELS,attachment,weaponStats,previewBuild,effectLines,EQUIPMENT} from './loadout.js';
const paths=['M10 32h26v-5h37v5h25v9H72v10H59V40H42l-4 14H28l3-14H10z','M19 24h65v15H49l-5 23H29l4-27H19z','M13 29h22v-5h40v8h20v9H63v21H49V41H35l-2 13H20l3-15H13z','M5 31h30v-9h24v9h44v8H64v7H47l-4 13H29l3-20H5z','M9 24h82v7h9v20H11V40H6V29h3zm24 27h14v15H33z','M5 31h35v-6h64v8H76v9H49l-7 18H28l6-20H5z'];
export function gunIcon(g){return `<svg class="gun-icon" viewBox="0 0 110 75" aria-hidden="true"><path d="${paths[g]}" fill="currentColor"/></svg>`}
export function reticleIcon(type){return `<svg class="reticle-icon" viewBox="0 0 60 60" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5">${type==='dot'?'<circle cx="30" cy="30" r="2" fill="currentColor"/>':type==='ring'?'<circle cx="30" cy="30" r="13"/><circle cx="30" cy="30" r="1.5" fill="currentColor"/>':type==='holo'?'<circle cx="30" cy="30" r="12"/><path d="M30 12v7m0 22v7M12 30h7m22 0h7"/><circle cx="30" cy="30" r="1"/>':type==='chevron'?'<path d="m23 34 7-8 7 8M30 37v7"/>':type==='duplex'?'<path d="M30 7v15m0 16v15M7 30h15m16 0h15" stroke-width="3"/><path d="M30 21v18M21 30h18" stroke-width=".7"/>':'<path d="M30 9v16m0 10v16M9 30h16m10 0h16"/><circle cx="30" cy="30" r="2"/>'}</svg>`}
function statsHTML(base,g,builds,preview,perks){const a=weaponStats(base,g,builds),b=weaponStats(base,g,preview),rows=[['DAMAGE',a.damage*(g===4?150/110:1),b.damage*(g===4?150/110:1),g===5?' / PELLET':'',true],['FIRE RATE',60/a.interval,60/b.interval,' RPM',true],['MAGAZINE',a.mag,b.mag,'',true],['RELOAD',a.reload*(perks.reload?.65:1),b.reload*(perks.reload?.65:1),' s',false],['RECOIL',a.recoil*100,b.recoil*100,'%',false],['AIM TIME',.22*a.ads*(perks.quickdraw?.8:1),.22*b.ads*(perks.quickdraw?.8:1),' s',false]];return rows.map(([name,x,y,unit,high])=>{const format=n=>name==='RELOAD'||name==='AIM TIME'?n.toFixed(2):Math.round(n),diff=Math.abs(x-y)>.001;return `<div class="weapon-stat"><small>${name}</small><strong>${format(x)}${diff?`<span class="stat-change ${(y>x)===high?'better':'worse'}"> → ${format(y)}</span>`:''}<em>${unit}</em></strong></div>`}).join('')}
function comparedPart(gun,item,builds){const old=attachment(gun,builds[gun]?.slots[item.slot]);if(!old||old.id===item.id)return item;const effects={};for(const key of new Set([...Object.keys(old.effects),...Object.keys(item.effects)])){const value=key==='magAdd'?(item.effects[key]||0)-(old.effects[key]||0):(item.effects[key]||1)/(old.effects[key]||1);if(key==='magAdd'?value!==0:Math.abs(value-1)>.005)effects[key]=value}return {...item,effects}}
const effectsHTML=item=>effectLines(item).map(x=>`<span class="${x.good?'better':'worse'}">${x.text}</span>`).join('');
const group=(name,body,extra='')=>`<section class="shop-group ${extra}"><h2>${name}</h2>${body||'<p class="empty-stock">All owned.</p>'}</section>`;
const cost=(label,disabled=false)=>`<em class="offer-cost ${disabled?'short-cash':''}">${label}</em>`;
function shopItem({name,meta='',desc='',icon='',status,disabled=false,attrs='',owned=false}){return `<button class="offer ${owned?'purchased':''}" ${attrs} ${disabled?'disabled':''}><span class="offer-top"><b>${name}</b>${cost(status,disabled&&!owned)}</span>${meta?`<small>${meta}</small>`:''}<span class="offer-body">${icon}${desc}</span></button>`}
function header(s){return `<header class="shop-header"><div class="shop-heading"><h1>${s.inspect?'ARSENAL':'LOADOUT'}</h1>${s.inspect?'':`<span>ROUND ${s.round+1}</span>`}</div>${s.inspect?'':`<strong class="shop-credits">${s.credits}<small> CR</small></strong>`}<div class="shop-actions"><button id="savequit">${s.inspect?'MAIN MENU':'SAVE & EXIT'}</button>${s.inspect?'':`<button class="shop-start" id="nextmatch">PLAY ROUND ${s.round+1}</button>`}</div></header>`}
function loadoutPanel(s){const {weapons,owned,builds,gun,perks,equipment,starting}=s,w=weapons[gun];return `<aside class="owned-loadout"><div class="owned-heading"><h2>EQUIPPED</h2><span>★ starting weapon</span></div><div class="owned-weapons">${owned.map(g=>`<div class="owned-weapon ${g===gun?'selected':''}"><button data-gun="${g}" aria-pressed="${g===gun}" title="${weapons[g].name} / ${weapons[g].label}">${weapons[g].name}</button><button data-start="${g}" class="start-star ${g===starting?'active':''}" aria-label="Start with ${weapons[g].name}" aria-pressed="${g===starting}">${g===starting?'★':'☆'}</button></div>`).join('')}</div><div class="owned-gun-title"><b>${w.name}</b>${Object.keys(builds[gun]?.slots||{}).length?'<button id="reset-build" title="Fit standard parts; keep purchases">RESET PARTS</button>':''}</div><div class="weapon-stats">${statsHTML(w,gun,builds,builds,perks)}</div><div class="owned-slots">${Object.entries(WEAPON_SLOTS[gun]).filter(([,items])=>items.some(a=>builds[gun]?.owned.includes(a.id))).map(([slot,items])=>{const available=items.filter(a=>builds[gun]?.owned.includes(a.id)),current=builds[gun]?.slots[slot]||'';return `<label><span>${SLOT_LABELS[slot]}</span><select aria-label="${w.name} ${SLOT_LABELS[slot]}" data-owned-slot="${slot}" ${available.length?'':'disabled'}><option value="">Standard</option>${available.map(a=>`<option value="${a.id}" ${a.id===current?'selected':''}>${a.name}</option>`).join('')}</select></label>`}).join('')||'<p class="standard-parts">Standard parts</p>'}</div><div class="owned-gear">${Object.entries(EQUIPMENT).map(([key,items])=>`<label><span>${key==='throwable'?'Grenade ×'+(perks.frags?4:2):'Killstreak'}</span><select data-owned-gear="${key}" aria-label="${key==='throwable'?'Grenade':'Killstreak'}" ${items.filter(a=>equipment.owned.includes(a.id)).length<2?'disabled':''}>${items.filter(a=>equipment.owned.includes(a.id)).map(a=>`<option value="${a.id}" ${a.id===equipment[key]?'selected':''}>${a.name}</option>`).join('')}</select></label>`).join('')}</div><div class="active-perks"><h3>ACTIVE PERKS</h3><div>${s.upgrades.filter(u=>perks[u.id]).map(u=>`<span title="${u.desc}">${u.name}</span>`).join('')||'<small>None</small>'}</div></div></aside>`}
export function loadoutHTML(s){s={...s,owned:WEAPON_ORDER.filter(g=>s.owned.includes(g))};if(s.inspect)return catalogHTML(s);const {weapons,offers,builds,owned,perks,equipment,credits,upgrades}=s;
 const guns=offers.weapons.map(g=>{const w=weapons[g],bought=owned.includes(g),price=w.price||220;return shopItem({name:w.name,icon:gunIcon(g),desc:`<span><small>${w.label}</small>${g===4?150:w.damage} damage${w.pellets>1?'/pellet':''} · ${w.mag} rounds</span>`,status:bought?'OWNED':price+' CR',owned:bought,disabled:!bought&&credits<price,attrs:`data-shop-gun="${g}" aria-label="${bought?'View':'Buy'} ${w.name}${bought?'':' for '+price+' credits'}"`})}).join('');
 const parts=offers.attachments.map(({gun,id})=>{const a=attachment(gun,id),bought=builds[gun]?.owned.includes(id),fit=builds[gun]?.slots[a.slot]===id;return shopItem({name:a.name,meta:weapons[gun].name+' / '+SLOT_LABELS[a.slot]+(builds[gun]?.slots[a.slot]&&!fit?' · replaces '+attachment(gun,builds[gun].slots[a.slot]).name:''),desc:`${a.reticle?reticleIcon(a.reticle):''}<span class="offer-effects">${fit?'<span>Current part</span>':effectsHTML(comparedPart(gun,a,builds))}</span>`,status:fit?'FITTED':bought?'FIT FREE':a.price+' CR',owned:bought,disabled:fit||!bought&&credits<a.price,attrs:`data-shop-part="${gun}:${id}" aria-label="${fit?'Fitted':bought?'Fit':'Buy and fit'} ${a.name} for ${weapons[gun].name}${bought?'':' · '+a.price+' credits'}"`})}).join('');
 const perkRows=offers.perks.map(id=>{const a=upgrades.find(u=>u.id===id),bought=perks[id];return shopItem({name:a.name,desc:a.desc,status:bought?'ACTIVE':a.price+' CR',disabled:bought||credits<a.price,owned:bought,attrs:`data-buy="${id}" aria-label="${bought?'Active':'Buy'} ${a.name}${bought?'':' for '+a.price+' credits'}"`})}).join('');
 const gear=offers.equipment.map(key=>{const [type,id]=key.split(':'),a=type==='perk'?upgrades.find(u=>u.id===id):EQUIPMENT[type].find(u=>u.id===id),bought=type==='perk'?perks[id]:equipment.owned.includes(id),fit=type==='perk'?bought:equipment[type]===id;return shopItem({name:a.name,desc:a.desc,status:fit?(type==='perk'?'ACTIVE':'EQUIPPED'):bought?'EQUIP FREE':a.price+' CR',owned:bought,disabled:fit||!bought&&credits<a.price,attrs:type==='perk'?`data-buy="${id}"`:`data-gear="${key}"`})}).join('');
 return `<div class="shop-shell">${header(s)}<main class="shop-board"><div class="shop-basics">${group('WEAPONS',guns)}${group('PERKS',perkRows)}${group('EQUIPMENT',gear)}</div>${group('ATTACHMENTS <small>changes vs fitted</small>',parts,'shop-parts')}${loadoutPanel(s)}</main><footer class="shop-status"><span id="loadout-status" role="status" tabindex="-1">${s.message||''}</span><span>Swap owned parts free</span></footer></div>`;
}
function catalogHTML(s){const {weapons,gun,slot,builds,perks,upgrades}=s,w=weapons[gun],items=WEAPON_SLOTS[gun][slot]||[];return `<div class="shop-shell catalog-shell">${header(s)}<main class="shop-board"><section class="shop-group"><h2>WEAPONS</h2><div class="catalog-guns">${WEAPON_ORDER.map(g=>`<button data-gun="${g}" class="${gun===g?'selected':''}" aria-pressed="${gun===g}">${gunIcon(g)}<span><b>${weapons[g].name}</b><small>${weapons[g].label}</small></span></button>`).join('')}</div><div class="weapon-stats">${statsHTML(w,gun,builds,builds,perks)}</div></section><section class="shop-group"><h2>${w.name} / ATTACHMENTS</h2><select class="catalog-slot" id="catalog-slot" aria-label="Attachment category">${Object.keys(WEAPON_SLOTS[gun]).map(k=>`<option value="${k}" ${k===slot?'selected':''}>${SLOT_LABELS[k]}</option>`).join('')}</select>${items.map(a=>`<div class="offer catalog-part"><span class="offer-top"><b>${a.name}</b>${cost(a.price+' CR')}</span><span class="offer-body">${a.reticle?reticleIcon(a.reticle):''}<span class="offer-effects">${effectsHTML(a)}</span></span></div>`).join('')}</section><section class="shop-group catalog-equipment"><h2>PERKS</h2>${upgrades.filter(u=>u.category==='PERK'||u.id==='frags').map(a=>`<div class="catalog-row"><b>${a.name}<em>${a.price} CR</em></b><small>${a.desc}</small></div>`).join('')}<h2>EQUIPMENT</h2>${Object.values(EQUIPMENT).flat().map(a=>`<div class="catalog-row"><b>${a.name}<em>${a.price?a.price+' CR':'STANDARD'}</em></b><small>${a.desc}</small></div>`).join('')}</section></main></div>`}
